import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DCluYYrN.js";const m=JSON.parse('{"title":"什么是 KernelSU？","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/guide/what-is-kernelsu.md","filePath":"zh_CN/guide/what-is-kernelsu.md"}'),l={name:"zh_CN/guide/what-is-kernelsu.md"};function n(i,e,s,h,d,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">什么是 KernelSU？ <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;什么是 KernelSU？ {#introduction}&quot;">​</a></h1><p>KernelSU 是 Android GKI 设备的 root 解决方案，它工作在内核模式，并直接在内核空间中为用户空间应用程序授予 root 权限。</p><h2 id="features" tabindex="-1">功能 <a class="header-anchor" href="#features" aria-label="Permalink to &quot;功能 {#features}&quot;">​</a></h2><p>KernelSU 的主要特点是它是<strong>基于内核的</strong>。KernelSU 运行在内核空间，所以它可以提供我们以前从未有过的内核接口。例如，我们可以在内核模式下为任何进程添加硬件断点；我们可以在任何进程的物理内存中访问，而无人知晓；我们可以在内核空间拦截任何系统调用; 等等。</p><p>此外，KernelSU 提供了 <a href="./metamodule.html">metamodule 系统</a>，这是一个可插拔的模块管理架构。与将挂载逻辑内置到核心的传统 root 方案不同，KernelSU 将此功能委托给 metamodule。这允许您安装 <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a> 等 metamodule，以提供对 <code>/system</code> 分区和其他分区的无系统修改。</p><h2 id="how-to-use" tabindex="-1">如何使用 <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;如何使用 {#how-to-use}&quot;">​</a></h2><p>请参考: <a href="./installation.html">安装</a></p><h2 id="how-to-build" tabindex="-1">如何构建 <a class="header-anchor" href="#how-to-build" aria-label="Permalink to &quot;如何构建 {#how-to-build}&quot;">​</a></h2><p>请参考: <a href="./how-to-build.html">如何构建</a></p><h2 id="discussion" tabindex="-1">讨论 <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;讨论 {#discussion}&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const _=a(l,[["render",n]]);export{m as __pageData,_ as default};
